-- Existing projects: run these if featured_content already exists
alter table public.featured_content add column if not exists image_enabled boolean not null default false;
alter table public.featured_content add column if not exists video_enabled boolean not null default false;
alter table public.featured_content add column if not exists tiktok_url text;


-- TikTok player autoplay
alter table public.featured_content add column if not exists tiktok_autoplay boolean not null default true;
